def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    opD = op.count('D')
    myD = my.count('D')

    if opD == 0:
        return 'C'

    if opD > n * 0.4:
        return 'D'

    if op[-1] == 'D':
        if my[-1] == 'D' and opD < n * 0.25:
            return 'C'
        return 'D'
    return 'C'
